describe('Live Data Timestamp Display', () => {
  beforeEach(() => {
    cy.visit('/live-data');
  });

  it('should display the last updated timestamp when live data is available', () => {
    cy.intercept('GET', '/api/live-data').as('getLiveData');
    cy.wait('@getLiveData');

    cy.get('[data-testid="live-data-container"]').should('be.visible');
    cy.get('[data-testid="last-updated-timestamp"]').should('be.visible');
    cy.get('[data-testid="last-updated-timestamp"]').should('contain', 'Updated:');
    cy.get('[data-testid="last-updated-timestamp"]').should('contain', '2 minutes ago');
    cy.get('[data-testid="data-value"]').should('contain', '15.2');
  });

  it('should display "No data available" when live data is not yet updated', () => {
    cy.intercept('GET', '/api/live-data', {
      statusCode: 200,
      body: {
        data: null,
        lastUpdated: null
      }
    }).as('getLiveDataEmpty');
    cy.wait('@getLiveDataEmpty');

    cy.get('[data-testid="live-data-container"]').should('be.visible');
    cy.get('[data-testid="last-updated-timestamp"]').should('be.visible');
    cy.get('[data-testid="last-updated-timestamp"]').should('contain', 'No data available');
    cy.get('[data-testid="data-value"]').should('contain', 'N/A');
  });
});
